// Approved Romanian for the glossary terms that block the Personality.co RO fill.
// Gender-avoiding by default. No slash or parenthetical forms: zero precedent across
// 9,610 existing Romanian strings in Personality.co.
const APPROVED = {
  'Results': 'rezultate',
  'Connection': 'conexiune',
  'Empathy': 'empatie',
  'Traits': 'trăsături',
  'Impact': 'impact',
  'Responsibility': 'responsabilitate',
  'Communication': 'comunicare',
  'Challenges': 'provocări',
  'Authenticity': 'autenticitate',
  'Interest': 'interes',
  'Adaptability': 'adaptabilitate',
  'Self-Awareness': 'conștiință de sine',
  'Emotional needs': 'nevoi emoționale',
  'coping': 'coping',
  'Personal Growth': 'dezvoltare personală',
  'Intimacy': 'intimitate',
  'Emotional bonds': 'legături emoționale',
  'Emotional Intelligence': 'inteligență emoțională',
  'Romantic relationships': 'relații romantice',
  'Career': 'carieră',
  'Family': 'familie',
  'Give': 'a oferi',
  'Receive': 'a primi',
  'Female': 'Femeie',
  'Male': 'Bărbat',
  'Single': 'Fără relație',
  'Very Low': 'Nivel foarte scăzut',
  'Low': 'Nivel scăzut',
  'Moderate': 'Nivel moderat',
  'High': 'Nivel ridicat',
  'Very High': 'Nivel foarte ridicat'
};
// Deliberately NOT written:
//   Strategic, Dominant  -> adjectives, source should be rewritten as nouns first
//   Experience, Skills, Review -> one glossary row carrying two meanings, must be split

const RO_LANG_ID = 770; // numeric; the write API rejects the ISO code

function page(nodeName) {
  let j; try { j = $(nodeName).first().json; } catch(e) { return []; }
  if (!j) return [];
  const a = j.data || j.terms || j.glossary_terms;
  return Array.isArray(a) ? a : [];
}
const all = page('Glossary p1').concat(page('Glossary p2'));
if (!all.length) throw new Error('glossary fetch returned nothing');

const seen = new Set();
const terms = [];
for (const t of all) {
  const id = t.id ?? t.term_id;
  const nm = String(t.term || '').trim();
  if (!nm || !id || seen.has(id)) continue;
  seen.add(id);
  terms.push({ id, term: nm, translatable: t.translatable !== false, translations: Array.isArray(t.translations) ? t.translations : [] });
}
const roOf = t => t.translations.find(x => x.langId === RO_LANG_ID || x.langIso === 'ro');

const withRoSlot = terms.filter(t => !!roOf(t)).length;
if (withRoSlot === 0) throw new Error('no term exposes a Romanian translation slot - check RO_LANG_ID');

const writes = [], notFound = [], alreadySet = [], notTranslatable = [];
for (const [name, ro] of Object.entries(APPROVED)) {
  const hit = terms.find(t => t.term.toLowerCase() === name.toLowerCase());
  if (!hit) { notFound.push(name); continue; }
  if (!hit.translatable) { notTranslatable.push(name); continue; }
  const cur = roOf(hit);
  const curVal = cur ? String(cur.translation || '').trim() : '';
  if (curVal) { alreadySet.push({ term: name, existing: curVal, proposed: ro }); continue; }
  writes.push({ id: hit.id, term: hit.term, ro });
}

// Payload shape verified on a single term (Results -> rezultate, HTTP 200).
const TEST_ONLY = false;
const selected = TEST_ONLY ? writes.slice(0, 1) : writes;
if (!selected.length) {
  return [{ json: { test_only: TEST_ONLY, nothing_to_write: true, already_has_ro_SKIPPED: alreadySet, payload: { terms: [] } } }];
}

return [{ json: {
  test_only: TEST_ONLY,
  ro_lang_id: RO_LANG_ID,
  planned_writes: writes.length,
  selected_this_run: selected.length,
  not_found_in_glossary: notFound,
  not_translatable_SKIPPED: notTranslatable,
  already_has_ro_SKIPPED: alreadySet,
  payload: { terms: selected.map(w => ({ id: w.id, translations: [{ langId: RO_LANG_ID, translation: w.ro }] })) },
  writes_detail: writes
} }];
